<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;
class StoreApplicationRequest extends FormRequest{public function authorize():bool{return true;}public function rules():array{return['program_id'=>['required','exists:programs,id'],'first_name'=>['required','string','max:80'],'last_name'=>['required','string','max:80'],'date_of_birth'=>['required','date','before:-15 years'],'gender'=>['required','in:female,male,other,prefer_not_to_say'],'email'=>['required','email','max:150'],'phone'=>['required','string','max:40'],'national_id'=>['nullable','string','max:80'],'address'=>['required','string','max:1000'],'city'=>['required','string','max:100'],'country'=>['required','string','max:100'],'highest_qualification'=>['required','string','max:150'],'institution'=>['required','string','max:180'],'graduation_year'=>['required','integer','min:1950','max:'.(date('Y')+1)],'grade_percentage'=>['nullable','numeric','min:0','max:100'],'statement'=>['nullable','string','max:3000'],'transcript'=>['required','file','mimes:pdf,jpg,jpeg,png','max:5120'],'identity_document'=>['required','file','mimes:pdf,jpg,jpeg,png','max:5120'],'confirmation'=>['accepted']];}}
